[tool.poetry]
name = "dotmac_starter_mt"
version = "0.9.0"
description = "Multi-tenant FastAPI starter"
authors = ["DotMac"]
readme = "README.md"
package-mode = false
# Build-tool version is part of the dependency contract: Poetry versions can
# compute different content hashes and normalise the same constraints
# differently. CI, Docker and bootstrap generation all derive from this exact
# native Poetry constraint; ranges are rejected by the architecture gate.
requires-poetry = "2.4.1"

[tool.poetry.dependencies]
python = ">=3.12,<3.14"
# The kernel, consumed as a package boundary (develop=true: editable, no copied
# modules, no import-path shims). It brings fastapi/sqlalchemy/pydantic/
# pydantic-settings/jinja2/argon2-cffi transitively; the assembly still declares
# the ones it uses directly below (uvicorn/gunicorn/psycopg/alembic/
# python-multipart/email-validator).
dotmac-kernel = { path = "packages/dotmac-kernel", develop = true }
# The shared UI design system (ADR-0006 U1), consumed as a package boundary on
# the same terms as the kernel: editable path dependency, no copied files, no
# import shims. It is dependency-free by design — adding it pulls in nothing —
# and the assembly's ONLY use of it is `app/assembly.py` composing its packaged
# static dir and its one stylesheet URL. Governed by
# `tests/architecture/test_ui_public_surface.py` (ADR-0006 D5).
dotmac-ui = { path = "packages/dotmac-ui", develop = true }
# The first INSTALLED STATEFUL MODULE (ADR-0006 M1) — composed on the same terms
# as the kernel and the UI package: editable path dependency, no copied files,
# no import shims. The assembly's only uses of it are the three lines in
# `app/assembly.py` (its manifest, its packaged template dir) and its version
# location in `alembic.ini`.
dotmac-template-studio = { path = "packages/dotmac-template-studio", develop = true }
# The second installable module (ADR-0006 M2). Same footing as the first: an
# editable path dependency, no copied files, no import shims.
dotmac-ticketing = { path = "packages/dotmac-ticketing", develop = true }
# The third installable module (ADR-0006 M3), and the first whose tables are
# PLATFORM CATALOG rather than tenant-scoped. Same footing as the other two.
#
# A path dependency is correct WITHIN this repository — package and assembly are
# released from one checkout. It is not correct ACROSS repositories: a consuming
# assembly such as the vendor control plane pins an exact released version from
# the private index, never a relative path.
dotmac-release-catalog = { path = "packages/dotmac-release-catalog", develop = true }
# The fourth installable module (ADR-0006 M4), and the second vendor-side one.
dotmac-entitlement-allocation = { path = "packages/dotmac-entitlement-allocation", develop = true }
# The durable vendor<->operator commercial agreement (ADR-0057 § 1). Like the
# two above it is vendor-side: `app/assembly.py` does not compose it, and the
# "assembly must not install vendor-only modules" contract below is what keeps
# that true rather than merely current.
dotmac-commercial-agreements = { path = "packages/dotmac-commercial-agreements", develop = true }
# The ISSUER half of WS8 (ADR-0057 § 2). Vendor-side, and the most strongly
# so of the three: it names the signing material that must never be reachable
# from a data plane, which is what the vendor-only contract below enforces.
dotmac-licensing = { path = "packages/dotmac-licensing", develop = true }
# Desired deployment intent, rollout, acknowledgement and reconciliation
# (ADR-0057 § 3). Vendor-side: it decides what a FLEET should run, which is
# not a thing any one deployment may hold.
dotmac-deployment-control = { path = "packages/dotmac-deployment-control", develop = true }
# ADR-0040 vendor-operations cohort. Both are platform-only and remain absent
# from this tenant assembly.
dotmac-platform-health = { path = "packages/dotmac-platform-health", develop = true }
dotmac-support-access = { path = "packages/dotmac-support-access", develop = true }
# The tenant half of the same ADR-0040 cohort. Declared so the packages are
# importable: the import-linter contracts below name `dotmac_forms` and
# `dotmac_workflow_runtime`, and a contract naming a package that is not on the
# path fails the build instead of checking it.
dotmac-forms = { path = "packages/dotmac-forms", develop = true }
# Initial learning source qualification; the reference assembly stays uncomposed.
# Publication requires replacing its in-tree Kernel dependency with a proven floor.
dotmac-learning = { path = "packages/dotmac-learning", develop = true }
dotmac-workflow-runtime = { path = "packages/dotmac-workflow-runtime", develop = true }
# Brand profile DATA (ADR-0057 § 2). Genuinely dual-plane, and the one module
# in the vendor programme that a tenant data plane legitimately installs —
# which is why it is deliberately NOT on the vendor-only forbidden list below.
dotmac-brand-profiles = { path = "packages/dotmac-brand-profiles", develop = true }
# The third installable module (ADR-0021), and the first whose consumer is a
# DIFFERENT assembly: the Tenant Workspace. This repository builds, tests and
# releases it, but `app/assembly.py` deliberately does NOT compose it and
# `alembic.ini` deliberately omits its lineage — the starter is a target
# application, not a workspace, and composing it here would put `mod_appdir`
# into every starter deployment. Its Postgres proof runs against a scratch
# database in `tests/test_application_directory_isolation.py` instead.
dotmac-application-directory = { path = "packages/dotmac-application-directory", develop = true }
# Optional stored-object lifecycle. Like application-directory, this repository
# builds and proves the package but deliberately does not compose its schema in
# the reference assembly; the first product adopter owns that cutover.
dotmac-files = { path = "packages/dotmac-files", develop = true }
# Optional bulk-import run ledger (ADR-0025). Same posture as the two above:
# built and proven here, composed by the first product adopter.
dotmac-imports = { path = "packages/dotmac-imports", develop = true }
# OIDC relying-party client (ADR-0017's 2026-08-14 amendment). STATELESS — no
# rows, no lineage, no namespace — so unlike the modules above it composes into
# nothing here; a consumer constructs an `OIDCClient` rather than installing a
# manifest. Built and proven here, adopted by the first product identity facet.
dotmac-auth-oidc = { path = "packages/dotmac-auth-oidc", develop = true }
# Approval state on two declared planes (ADR-0026). Same posture as the three
# above: built and proven here, composed by the first product adopter.
dotmac-approvals = { path = "packages/dotmac-approvals", develop = true }
dotmac-numbering = { path = "packages/dotmac-numbering", develop = true }
# Tenant employment-directory owner extracted product-first from ERP. Built and
# proven here; the clean Backoffice assembly is its first exact-pin consumer.
dotmac-people = { path = "packages/dotmac-people", develop = true }
# ADR-0058 ISP essential-domain cohort. Built and proven here, but deliberately
# uncomposed and release-unallowlisted until each source product's named cutover.
dotmac-customers = { path = "packages/dotmac-customers", develop = true }
dotmac-service-catalog = { path = "packages/dotmac-service-catalog", develop = true }
dotmac-qualification = { path = "packages/dotmac-qualification", develop = true }
dotmac-services = { path = "packages/dotmac-services", develop = true }
dotmac-usage = { path = "packages/dotmac-usage", develop = true }
dotmac-usage-rating = { path = "packages/dotmac-usage-rating", develop = true }
dotmac-service-access-policy = { path = "packages/dotmac-service-access-policy", develop = true }
dotmac-inbox-operations = { path = "packages/dotmac-inbox-operations", develop = true }
dotmac-workforce = { path = "packages/dotmac-workforce", develop = true }
dotmac-fx-policy = { path = "packages/dotmac-fx-policy", develop = true }
# The customer-journey owners (2026-08-22 audit of Sub PR #2624). Built and
# proven here, deliberately uncomposed and release-unallowlisted until Sub's
# named cutover; Service Changes additionally waits on cohorts 2-5.
dotmac-service-orders = { path = "packages/dotmac-service-orders", develop = true }
dotmac-payments = { path = "packages/dotmac-payments", develop = true }
dotmac-service-changes = { path = "packages/dotmac-service-changes", develop = true }
dotmac-operational-escalations = { path = "packages/dotmac-operational-escalations", develop = true }
dotmac-response-obligations = { path = "packages/dotmac-response-obligations", develop = true }
# Tenant-only stock-ledger and traceability owner (ADR-0036). The network
# suite reuses this owner for equipment while it is stocked; deployment does
# not turn Network Inventory into a second quantity or valuation writer.
dotmac-inventory = { path = "packages/dotmac-inventory", develop = true }
# Tenant-only durable-unit owner (ADR-0037). Network modules bind to an asset
# opaquely and retain only network-specific identity and behavior.
dotmac-assets = { path = "packages/dotmac-assets", develop = true }
# ADR-0038 network-suite-v1 candidates. Built and validated together here, but
# not composed by the reference assembly and not adopted incrementally in Sub.
dotmac-ipam = { path = "packages/dotmac-ipam", develop = true }
dotmac-network-inventory = { path = "packages/dotmac-network-inventory", develop = true }
dotmac-network-observability = { path = "packages/dotmac-network-observability", develop = true }
dotmac-network-topology = { path = "packages/dotmac-network-topology", develop = true }
dotmac-network-assurance = { path = "packages/dotmac-network-assurance", develop = true }
dotmac-network-control = { path = "packages/dotmac-network-control", develop = true }
dotmac-fiber-plant = { path = "packages/dotmac-fiber-plant", develop = true }
dotmac-network-access = { path = "packages/dotmac-network-access", develop = true }
dotmac-pon-access = { path = "packages/dotmac-pon-access", develop = true }
# Tenant-only provider-neutral position observations (ADR-0039). Built and
# proven here; Assets keeps a durable unit's authoritative location and product
# owners keep every consequence, so the reference assembly installs nothing.
dotmac-positioning = { path = "packages/dotmac-positioning", develop = true }
# Optional dual-plane timer identity and generation owner. Delivery stays in
# the kernel outbox relay; each real adopter composes its own selected planes.
dotmac-durable-timers = { path = "packages/dotmac-durable-timers", develop = true }
dotmac-billing = { path = "packages/dotmac-billing", develop = true }
dotmac-collections = { path = "packages/dotmac-collections", develop = true }
# Reusable recurring-commercial owner. Built and proven here; real adopters
# compose an explicit plane while this reference assembly installs neither.
dotmac-subscriptions = { path = "packages/dotmac-subscriptions", develop = true }
# The external connector control plane (ADR-0024). Built and proven here;
# its runtime is the separate `dotmac_integrator` assembly, so the reference
# assembly deliberately does not compose the `ig` lineage.
dotmac-integration = { path = "packages/dotmac-integration", develop = true }
# Immutable, provider-neutral external media facts. Built and proven here but
# deliberately not composed by Starter or any product while adoption is paused.
dotmac-media-observations = { path = "packages/dotmac-media-observations", develop = true }
# Tenant-only outbound campaign progression (ADR-0056). Built and proven here,
# composed first by Sub and then by Backoffice; the reference assembly does not
# install its lineage or import it from `app`.
dotmac-campaigns = { path = "packages/dotmac-campaigns", develop = true }
# Tenant-only editorial content owner extracted product-first from Mkt. Built
# and proven here; Backoffice remains the first future exact-pin adopter.
dotmac-content = { path = "packages/dotmac-content", develop = true }
# Tenant-only publication intent, immutable target attempts and reconciled
# outcomes. Built and proven here; Backoffice is the first candidate adopter.
dotmac-publishing = { path = "packages/dotmac-publishing", develop = true }
# Tenant-only website composition and immutable local release snapshots.
# Greenfield after the fleet audit; Backoffice is the first candidate adopter.
dotmac-sites = { path = "packages/dotmac-sites", develop = true }
# Tenant-only referral programme/attribution owner extracted from Sub. This
# reference assembly builds and proves the package but does not compose `rf`.
dotmac-referrals = { path = "packages/dotmac-referrals", develop = true }
# Tenant-only reseller identity, hierarchy and delegated-authority owner
# extracted from Sub. The reference assembly proves but does not compose `rm`.
dotmac-reseller-management = { path = "packages/dotmac-reseller-management", develop = true }
# ERP/Backoffice/general publication-prep cohort. These distributions are built
# and governed here, but remain uncomposed and release-unallowlisted until an
# exact-pin product adopter and exact-commit Observer proof exist for each one.
dotmac-accounting = { path = "packages/dotmac-accounting", develop = true }
dotmac-analytics = { path = "packages/dotmac-analytics", develop = true }
dotmac-banking = { path = "packages/dotmac-banking", develop = true }
dotmac-documents = { path = "packages/dotmac-documents", develop = true }
dotmac-expenses = { path = "packages/dotmac-expenses", develop = true }
dotmac-finance = { path = "packages/dotmac-finance", develop = true }
dotmac-inbox = { path = "packages/dotmac-inbox", develop = true }
dotmac-party = { path = "packages/dotmac-party", develop = true }
dotmac-payables = { path = "packages/dotmac-payables", develop = true }
dotmac-payroll = { path = "packages/dotmac-payroll", develop = true }
dotmac-procurement = { path = "packages/dotmac-procurement", develop = true }
dotmac-projects = { path = "packages/dotmac-projects", develop = true }
dotmac-records = { path = "packages/dotmac-records", develop = true }
dotmac-surveys = { path = "packages/dotmac-surveys", develop = true }
dotmac-tax = { path = "packages/dotmac-tax", develop = true }
dotmac-work-orders = { path = "packages/dotmac-work-orders", develop = true }
# ADR-0040 tenant ISP parity cohort. The packages exchange only opaque values
# through their adopting assembly and never import one another.
dotmac-remote-access = { path = "packages/dotmac-remote-access", develop = true }
dotmac-compliance-reporting = { path = "packages/dotmac-compliance-reporting", develop = true }
dotmac-ai-operations = { path = "packages/dotmac-ai-operations", develop = true }
# Tenant-only, privacy-minimised first-party website observations and
# deterministic projections (ADR-0055). The adopting product supplies origin,
# event, consent and retention policy; the reference assembly installs none.
dotmac-web-analytics = { path = "packages/dotmac-web-analytics", develop = true }
# Tenant sales authority through the immutable accepted Quote (ADR-0033).
# Built and proven here; Sub composes the first `sa` lineage after shadowing.
dotmac-sales = { path = "packages/dotmac-sales", develop = true }
# Stateless semantic projection and rendering for immutable issued-document
# facts. It is installed for verification here, but not composed or releasable.
dotmac-document-rendering = { path = "packages/dotmac-document-rendering", develop = true }
dotmac-fulfillment = { path = "packages/dotmac-fulfillment", develop = true }
fastapi = "^0.115"
uvicorn = {extras = ["standard"], version = "^0.30"}
gunicorn = "^22.0"
sqlalchemy = "^2.0"
psycopg = {extras = ["binary"], version = "^3.2"}
alembic = "^1.13"
pydantic = "^2.9"
pydantic-settings = "^2.5"
email-validator = "^2.2"
jinja2 = "^3.1"
python-multipart = "^0.0.32"
argon2-cffi = "^25.1.0"

[tool.poetry.group.dev.dependencies]
# The deployment facility is a BUILD-TIME tool, so it belongs here and not
# in `main`: the Dockerfile runs `poetry install --only main`, and a
# renderer that ships inside every production image is a dependency nobody
# audits protecting nothing. CI and deployment hosts install the RELEASED
# distribution by exact version; this path entry is what makes the source
# testable in the repository that owns it (ADR-0070).
dotmac-deployment-foundation = { path = "packages/dotmac-deployment-foundation", develop = true }
# Self-hosted runner policy is a build/host-control facility, not application
# runtime. The provider adapter is discovered only by its offline renderer;
# neither distribution ships in the Starter image or handles a request.
dotmac-runner-transport = { path = "packages/dotmac-runner-transport", develop = true }
dotmac-runner-transport-github-actions = { path = "packages/dotmac-runner-transport-github-actions", develop = true }
pytest = "^8.3"
pytest-asyncio = "^0.24"
httpx = "^0.27"
ruff = "^0.6"
mypy = "^1.11"
pytest-cov = "^7.1.0"
import-linter = "^2.13"
bandit = "^1.9.4"
pre-commit = "^4.6.0"
cryptography = "^45"
# Build/test input only. The Starter assembly never hosts provider plugins;
# dotmac_integrator pins the independently released connector at runtime.
dotmac-connector-whatsapp = { path = "packages/dotmac-connector-whatsapp", develop = true }
dotmac-connector-meta-social = { path = "packages/dotmac-connector-meta-social", develop = true }
dotmac-connector-paystack = { path = "packages/dotmac-connector-paystack", develop = true }
dotmac-connector-flutterwave = { path = "packages/dotmac-connector-flutterwave", develop = true }
dotmac-connector-linkedin = { path = "packages/dotmac-connector-linkedin", develop = true }
dotmac-connector-mono = { path = "packages/dotmac-connector-mono", develop = true }
dotmac-connector-remita = { path = "packages/dotmac-connector-remita", develop = true }
dotmac-connector-nira = { path = "packages/dotmac-connector-nira", develop = true }
dotmac-connector-sub-accounting = { path = "packages/dotmac-connector-sub-accounting", develop = true }
dotmac-connector-traccar = { path = "packages/dotmac-connector-traccar", develop = true }
dotmac-app-sync = { path = "packages/dotmac-app-sync", develop = true }

[tool.ruff]
line-length = 88
target-version = "py312"

[tool.ruff.lint]
select = ["E", "W", "F", "I", "B", "C4", "UP", "S", "RUF"]
ignore = [
    "B008",  # FastAPI dependency injection uses calls in defaults.
    "S101",  # asserts (tests; also narrowed per-file below)
]

[tool.ruff.lint.per-file-ignores]
"tests/*" = ["S105", "S106"]
"alembic/*" = ["E501"]
# EVERY migration lineage, in one rule rather than a path per package.
#
# Alembic files carry long DDL and GRANT literals, and wrapping them is worse
# than the long line: a grant split across two string fragments stops being
# greppable, which is the property those statements are written as literals to
# have. This covers the assembly's `alembic/` above, the kernel base migrations
# that moved into the package in Task 1c, and every installable module's own
# lineage — including ones not yet written, so the third module does not
# rediscover this as a one-off exemption the way it would with a path list.
"packages/*/src/*/migrations/*" = ["E501"]
"scripts/*" = ["S603", "S607"]  # trusted local ops tooling invoking git/docker

[tool.mypy]
python_version = "3.12"
ignore_missing_imports = true
disallow_untyped_defs = false
check_untyped_defs = true
warn_unused_ignores = true

# The vendor-side modules are held to FULLY TYPED contracts (the fleet-wide
# typed-contracts standard), which the assembly-wide settings above deliberately
# are not: `app/` predates the standard and relaxing it there is tracked debt.
# A new module has no such history, so it starts strict — and every one of these
# packages ships `py.typed`, meaning a consuming assembly's type-checker treats
# these annotations as the contract.
[[tool.mypy.overrides]]
module = [
    "dotmac_entitlement_allocation.*",
    "dotmac_commercial_agreements.*",
    "dotmac_licensing.*",
    "dotmac_deployment_control.*",
    "dotmac_platform_health.*",
    "dotmac_support_access.*",
    "dotmac_brand_profiles.*",
    "dotmac_files.*",
    "dotmac_approvals.*",
    "dotmac_numbering.*",
    "dotmac_people.*",
    "dotmac_customers.*",
    "dotmac_service_catalog.*",
    "dotmac_qualification.*",
    "dotmac_services.*",
    "dotmac_usage.*",
    "dotmac_usage_rating.*",
    "dotmac_service_access_policy.*",
    "dotmac_inbox_operations.*",
    "dotmac_workforce.*",
    "dotmac_fx_policy.*",
    "dotmac_service_orders.*",
    "dotmac_payments.*",
    "dotmac_service_changes.*",
    "dotmac_operational_escalations.*",
    "dotmac_response_obligations.*",
    "dotmac_inventory.*",
    "dotmac_assets.*",
    "dotmac_ipam.*",
    "dotmac_network_inventory.*",
    "dotmac_network_observability.*",
    "dotmac_network_topology.*",
    "dotmac_network_assurance.*",
    "dotmac_network_control.*",
    "dotmac_fiber_plant.*",
    "dotmac_network_access.*",
    "dotmac_pon_access.*",
    "dotmac_positioning.*",
    "dotmac_durable_timers.*",
    "dotmac_billing.*",
    "dotmac_collections.*",
    "dotmac_subscriptions.*",
    "dotmac_imports.*",
    "dotmac_integration.*",
    "dotmac_media_observations.*",
    "dotmac_campaigns.*",
    "dotmac_content.*",
    "dotmac_publishing.*",
    "dotmac_sites.*",
    "dotmac_referrals.*",
    "dotmac_reseller_management.*",
    "dotmac_accounting.*",
    "dotmac_analytics.*",
    "dotmac_banking.*",
    "dotmac_documents.*",
    "dotmac_expenses.*",
    "dotmac_finance.*",
    "dotmac_inbox.*",
    "dotmac_party.*",
    "dotmac_payables.*",
    "dotmac_payroll.*",
    "dotmac_procurement.*",
    "dotmac_projects.*",
    "dotmac_records.*",
    "dotmac_surveys.*",
    "dotmac_tax.*",
    "dotmac_work_orders.*",
    "dotmac_remote_access.*",
    "dotmac_compliance_reporting.*",
    "dotmac_ai_operations.*",
    "dotmac_web_analytics.*",
    "dotmac_sales.*",
    "dotmac_document_rendering.*",
    "dotmac_forms.*",
    "dotmac_learning.*",
    "dotmac_workflow_runtime.*",
    "dotmac_fulfillment.*",
    "dotmac_release_catalog.*",
    "dotmac_auth_oidc.*",
    "dotmac_connector_whatsapp.*",
]
disallow_untyped_defs = true
disallow_incomplete_defs = true
disallow_untyped_calls = true
disallow_any_generics = true
warn_return_any = true
no_implicit_reexport = true
strict_equality = true

[tool.bandit]
# Alembic migrations (assembly `alembic/` + the kernel base migrations, which
# moved into the package in Task 1c) build DDL from in-code constants, not
# user input — excluded from the SQL-string heuristics like `alembic/`.
exclude_dirs = [
    "tests",
    "alembic",
    "packages/dotmac-kernel/src/dotmac_kernel/migrations",
    # A module's own lineage, for the SAME reason as `alembic/` and the
    # kernel's above: a migration builds DDL from in-code constants, never from
    # user input.
    #
    # Listed per path because bandit's `exclude_dirs` does not glob here -- a
    # `packages/*/src/*/migrations` pattern is accepted silently and still
    # scans, which was verified rather than assumed. Each new stateful module
    # that hits B608 adds its line.
    #
    # This is not cosmetic. Without it B608 fires on a RELEASED migration, and
    # the cheapest way to silence it is to EDIT that file -- which is exactly
    # what happened to `nu_0001_numbering.py` after
    # `dotmac-numbering-v0.1.0a2` shipped, giving one revision id two file
    # contents while `alembic_version` recorded only that the revision ran.
    # Removing the incentive is the durable half of that repair.
    "packages/dotmac-numbering/src/dotmac_numbering/migrations",
    "packages/dotmac-payments/src/dotmac_payments/migrations",
    # The shipped test kit (kernel-boundary Task 5) is test-support code — its
    # provider CONTRACT is expressed as asserts (the pytest idiom), same
    # category as the excluded `tests/`, so B101 is expected, not a finding.
    "packages/dotmac-kernel/src/dotmac_kernel/testing",
]

[tool.pytest.ini_options]
testpaths = ["tests"]
addopts = "-q"
pythonpath = ["."]
markers = [
    # Not deselected by default — CI must run these. The marker exists so a
    # developer chasing a fast loop can `-m 'not slow'` deliberately, rather
    # than the suite quietly skipping the expensive proofs for everyone.
    "slow: builds an artifact or shells out; seconds, not milliseconds",
]

