[[tool.importlinter.contracts]]
# ADR-0070. The deployment facility runs on a build runner, a CI job and a
# deployment host — none of which has a database, a web framework or a tenant,
# and none of which should acquire one in order to validate a descriptor. This
# is the same one-way shape `dotmac-ui` holds, for the same reason.
#
# Stated as its own contract rather than folded into "Modules must not import
# the assembly" because the facility is NOT a module: it has no manifest, no
# `mod_*` namespace and no lineage, and filing it with the modules would send
# the next reader looking for all three.
name = "The deployment foundation must not import the kernel, the UI or the assembly"
type = "forbidden"
source_modules = ["dotmac_deployment_foundation"]
forbidden_modules = ["app", "dotmac_kernel", "dotmac_ui"]

[[tool.importlinter.contracts]]
# The other direction, and the one that actually decays. Nothing stops an
# application service from importing a renderer "just to read the descriptor",
# and the first one that does makes the facility a runtime dependency of the
# product it is supposed to deploy.
name = "The assembly and the kernel must not import the deployment foundation"
type = "forbidden"
source_modules = ["app", "dotmac_kernel"]
forbidden_modules = ["dotmac_deployment_foundation"]

[[tool.importlinter.contracts]]
name = "Kernel must not import the assembly"
type = "forbidden"
source_modules = ["dotmac_kernel"]
forbidden_modules = ["app"]

# ADR-0006 § 2: the dependency direction is one-way,
# `assembly → module → dotmac-ui → dotmac-kernel`. Two contracts pin the two
# ends of it. The kernel end is absolute — a kernel that reached forward into
# the presentation system would make the UI package un-releasable
# independently.
[[tool.importlinter.contracts]]
name = "Kernel must not import the UI package"
type = "forbidden"
source_modules = ["dotmac_kernel"]
forbidden_modules = ["dotmac_ui"]

# The UI end is pinned STRONGER than ADR-0006 § 2 requires. The ADR permits
# `dotmac-ui → dotmac-kernel`; at 0.1.0a1 the package takes no such dependency,
# and that is load-bearing rather than incidental: it is what lets `dotmac_erp`
# — which has adopted no kernel at all — consume the design system without
# adopting anything else first. Relaxing this contract is therefore a decision
# about ERP's adoption path, which is exactly why it should require editing
# this file. (The companion pytest guard additionally forbids a web framework,
# an ORM, and a templating engine, which import-linter cannot express here.)
[[tool.importlinter.contracts]]
name = "UI package must not import the kernel or the assembly"
type = "forbidden"
source_modules = ["dotmac_ui"]
forbidden_modules = ["dotmac_kernel", "app"]

# The MODULE end of the same one-way direction. A module may import the kernel
# (and, if it needed to, `dotmac-ui`); it may never import the ASSEMBLY that
# installs it, or another module. The assembly rule is what keeps a module
# releasable on its own — a module that reached into `app` would only run inside
# this one repository. The module-to-module rule is the same independence rule
# features already have, for the same reason: cross-module composition is an
# htmx-fetched fragment or a service call, never an import (ADR-0006 § 2).
#
# Only one module exists today, so "modules do not import each other" has
# nothing to bite on yet; the contract is written now so the SECOND module
# inherits the rule instead of discovering it.
